# Riferimento al nodo AnimationTree aggiunto a Player
@onready var animation_tree: AnimationTree = $AnimationTree

# Gestore della riproduzione per l'AnimationNodeStateMachine
var playback: AnimationNodeStateMachinePlayback


func _ready() -> void:
	# Recuperiamo l'oggetto di riproduzione dai parametri dell'AnimationTree
	playback = animation_tree["parameters/playback"]


func play_state(state_name: String) -> void:
	# travel() guida la macchina verso lo stato desiderato usando le transizioni del grafo
	if playback:
		playback.travel(state_name)


func set_movement_condition(moving: bool) -> void:
	# Impostiamo una Advance Condition per attivare transizioni automatiche
	animation_tree["parameters/conditions/is_moving"] = moving
